-- ruRU locale for quest_template, scoped to quests started by creatures on map 1220 (Broken
-- Isles). Most quest text on this server already has ruRU coverage (~1020 of 1075 map-1220
-- quests) - this file closes the remaining gap (55 quests with no ruRU row at all). Most of
-- these are short profession "Work Order"/"Supplies Needed" titles with no LogDescription/
-- QuestDescription (base text is empty for those fields too, nothing to translate there); a
-- handful of narrative quests have full flavor text, translated below.

DELETE FROM `quest_template_locale` WHERE `ID` IN (39840,39841,40857,41171,41187,41188,41207,41223,41235,41237,41267,41288,41292,41312,41326,41327,41338,41339,41350,41633,41635,41639,41640,41643,41645,41649,41651,41652,41653,41655,41658,41661,41665,41669,41671,41675,41676,41677,43474,43475,43476,43477,43478,43879,43880,43885,46997,47010,47012,47014,47069,47073,47074,47075,47078) AND `locale` = 'ruRU';
