INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`) VALUES
(39840, 'ruRU', 'Одобрение Совета', 'Поговори с Кадгаром в Даларане и попроси разрешения построить Кузницу обелиума.', 'Результаты оказались весьма разочаровывающими. Прокаливание - процесс капризный, им лучше заниматься алхимикам и кузнецам. И всё же я рассчитывал получить больше, чем жалкие ДВЕ КРУПИЦЫ обелиума.$b$bДля более эффективной реакции нам понадобится особая кузница, а чтобы её получить...$b$b...нам нужно разрешение Совета Шестерых.'),
(39841, 'ruRU', 'Друзья среди простолюдинов', 'Доложи Оксане Демонобой в Нижнем Городе.', 'Мой связной - некая Оксана Демонобой. Она отказалась от приглашения в сам Даларан, предпочитая оставаться в канализации Нижнего Города.$b$bЕсли кто на этой скале и знает, как правильно построить Кузницу обелиума, так это она.$b$bАх да, и приглядывай за спиной, пока будешь там внизу, $n.'),
(40857, 'ruRU', 'По кусочкам', 'Встреться с Бранном Бронзобородом в Штормхейме.', 'Столько артефактов нужно занести в каталог, а времени вечно не хватает.$b$bРад снова видеть тебя, $n. Бранн Бронзобород и Лига исследователей сейчас в Штормхейме, и им бы пригодилась твоя помощь в поисках древней реликвии титанов.$b$bБранн расскажет подробности, когда ты прибудешь.'),
(41171, 'ruRU', 'Реликварий зовёт', 'Встреться с Тей''теланом Кровавым Стражем в Азсуне.', 'Тей''телан из Реликвария попросил меня прислать любого, кто сможет помочь им в Азсуне.$b$bРаз уж ты случайно заглянул в мою лавку, я подумал, что ты не откажешься отправиться туда, $n.$b$bА мне пора возвращаться к работе. Столько дел, и так мало помощи.$b$b<Дэринесс вздыхает.>'),
(41187, 'ruRU', 'Студент на разведке', 'Успешно выполни 20 замеров в присутствии Лурона.', 'Я послал за кем-то, потому что мне стало трудно совмещать свои исследования с обучением помощника.$b$bЯ надеялся, что ты сможешь снова показать ему, что к чему. Освежить его знания о геодезии.$b$bПросто поговори с ним, когда будешь готов.'),
(41188, 'ruRU', 'Логово Нелтариона: Сбился с пути', 'Отправляйся в Логово Нелтариона и верни древний артефакт Вышегорья.', 'Я изучал историю Хална Вышегорья, легендарного воина времён Войны древних, в честь которого названы эти земли.$b$bПо слухам, некоторые его личные вещи были принесены сюда после его смерти и затерялись во времени.$b$bПокопавшись в архивах, я полагаю, что обнаружил местонахождение одного из его артефактов - в месте под названием Логово Нелтариона.$b$bЯ не боец, $n, а вот ты - да. Отправишься за этим артефактом для меня?'),
